  try{ dat=typeof ILDATA!=="undefined"?ILDATA:null; }catch(e){ return false; }   /* x_i18n_data.js not initialised yet (script order): try again later */
  try{
    if(dat&&dat.z!=null){ j=JSON.parse(typeof dlrUnz==="function"?dlrUnz(dat.z,dat.n):ilUnzSlow(dat.z,dat.n)); }
  }catch(e){ try{ console.error("i18n: dictionary failed",e); }catch(e2){} }
