    const segs=ar.split(/\{\d+\}/), ids=(ar.match(/\{(\d+)\}/g)||[]).map(x=>+x.slice(1,-1));
    if(segs.length<2) continue;
    const S=(segs.join("").match(/[\u0621-\u063F\u0641-\u064A\u0671-\u06D3]/g)||[]).length, weak=S<4;   /* few literal letters: only numbers / short codes may fill the slots ("{0} من {1}") */
    let rx; try{ rx=new RegExp("^"+segs.map(ilEsc).join(weak?"([+\\-\u2212]?\\d[\\d.,+\\-\u2212%:/\u00b0\u00d7\u00b7]*|[A-Za-z]{1,6}\\d*)":"([\\s\\S]+?)")+"$"); }catch(e){ continue; }
