    if(r==null&&lv===0){ const ss=k.split(/(?<=[.!?؟])\s+/); if(ss.length>1){ const ts=ss.map(s=>IL_AR.test(s)?ilTrans(s,false,0):s); if(ts.every(x=>x!=null)) r=ts.join(" "); } }
