/* translate first, then cut at n characters (at a word boundary in English) with an ellipsis: a text truncated in Arabic could not be matched in the dictionary */
function ilTrunc(s,n){ s=ilT(String(s==null?"":s)); if(s.length<=n) return s; if(IL.lang=="en"){ const c=s.slice(0,n+1).replace(/\s+\S*$/,""); return (c.length>n*0.6?c:s.slice(0,n))+"…"; } return s.slice(0,n)+"…"; }
