/* a run of sibling nodes (text + inline formatting elements such as <b>, no block elements) is one sentence: translate it as a unit (the extractor emits such chunks whole) */
const ilSer=n=>n.nodeType===3?n.data.replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/\u00a0/g,"&nbsp;"):n.outerHTML;
