  const h=IL.hn.get(root); if(h){ IL.hn.delete(root); h.forEach(x=>{ if(x.en.every(n=>n.parentNode===root)){ x.ar.forEach(n=>root.insertBefore(n,x.en[0])); x.en.forEach(n=>root.removeChild(n)); } }); }
